package vn.iotstar.service.impl; import lombok.RequiredArgsConstructor; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; import vn.iotstar.service.EmailService; @Service @RequiredArgsConstructor public class EmailServiceImpl implements EmailService{private final JavaMailSender mail; public void sendOtp(String email,String otp,String subject){SimpleMailMessage m=new SimpleMailMessage();m.setTo(email);m.setSubject(subject);m.setText("Mã OTP của bạn là: "+otp+". Mã có hiệu lực 5 phút.");mail.send(m);}}